BEGIN;
SET ROLE wo_owner;
COMMENT ON TABLE wo_v2.products IS '产品共同属性。';
COMMENT ON COLUMN wo_v2.products.id IS '产品内部稳定 ID，不使用外部登记编码作为主键。';
COMMENT ON COLUMN wo_v2.products.name IS '产品官方名称。';
COMMENT ON COLUMN wo_v2.products.product_code IS '经官方确认属于产品层的业务代码；未取得或层级不明时为空，不用登记编码、份额码或来源请求 ID 代填。';
COMMENT ON COLUMN wo_v2.products.registration_code IS '官方产品登记编码，与 product_code 分列保存；官方身份充分但未取得编码时为空，不编造，按字符串保留前导零。';
COMMENT ON COLUMN wo_v2.products.manager_name IS '管理人当前业务名称。';
COMMENT ON COLUMN wo_v2.products.risk_level IS '官方披露的风险等级；缺失时为空，不自动生成内部评级。';
COMMENT ON COLUMN wo_v2.products.currency IS '产品币种，如人民币 CNY。';
COMMENT ON COLUMN wo_v2.products.is_public IS '公募属性；表示是否已确认属于公募产品。';
COMMENT ON TABLE wo_v2.shares IS '份额与目录业务属性。';
COMMENT ON COLUMN wo_v2.shares.id IS '份额内部稳定 ID，用于净值、指标、详情及本地自选关联。';
COMMENT ON COLUMN wo_v2.shares.product_id IS '所属产品的内部 ID。';
COMMENT ON COLUMN wo_v2.shares.name IS '份额名称；默认份额使用已确认的未区分份额表示。';
COMMENT ON COLUMN wo_v2.shares.share_code IS '官方独立份额代码；未披露或默认份额没有独立代码时为空，不用 A/B 名称、产品码或销售码推定。';
COMMENT ON COLUMN wo_v2.shares.is_default IS '是否为官方确认单一净值序列后建立的默认份额。';
COMMENT ON COLUMN wo_v2.shares.inception_date IS '有官方依据且适用于本份额的成立日期；未知时为空。';
COMMENT ON COLUMN wo_v2.shares.lifecycle_state IS '份额当前存续、终止或未知状态；不从采集失败推断终止。';
COMMENT ON COLUMN wo_v2.shares.operating_mode IS '份额运作形态，用于解释持有、封闭、定开及现金管理等限制。';
COMMENT ON COLUMN wo_v2.shares.restriction_days IS '经核实用于目录准入的实际限制天数，0至31天；不是产品总存续期，未知记录留本地待处理。';
COMMENT ON COLUMN wo_v2.shares.collection_capability IS '是否达到约定历史和披露要求的采集能力结论；不是单次任务执行结果。';
COMMENT ON COLUMN wo_v2.shares.catalog_updated_at IS '目录业务内容最近变化的时间；不是每次抓取时间。';
COMMENT ON COLUMN wo_v2.shares.collection_epoch IS '当前写入状态随机令牌；相关事实、依据或计算配置真实变化及最后依据撤销时轮换，拒绝旧任务覆盖，不保存历史且不公开。';
COMMENT ON TABLE wo_v2.sales_offerings IS '销售关系。';
COMMENT ON COLUMN wo_v2.sales_offerings.id IS '销售关系的内部行 ID，兼容上游未提供销售代码的情况。';
COMMENT ON COLUMN wo_v2.sales_offerings.share_id IS '被销售份额的内部 ID。';
COMMENT ON COLUMN wo_v2.sales_offerings.channel_key IS '销售渠道的稳定配置键，不随渠道显示名称变化。';
COMMENT ON COLUMN wo_v2.sales_offerings.channel_name IS '销售渠道当前显示名称。';
COMMENT ON COLUMN wo_v2.sales_offerings.sales_code IS '该渠道使用的销售代码；缺失时为空，与产品码/份额码独立，不因同值混用。';
COMMENT ON TABLE wo_v2.sources IS '数据来源与取值排序。';
COMMENT ON COLUMN wo_v2.sources.id IS '数据来源的稳定配置键，与采集适配器配置对应。';
COMMENT ON COLUMN wo_v2.sources.name IS '数据来源的显示名称。';
COMMENT ON COLUMN wo_v2.sources.kind IS '来源类别，区分销售渠道来源和管理人来源。';
COMMENT ON COLUMN wo_v2.sources.priority IS '配置的同类别来源选用优先级。';
COMMENT ON TABLE wo_v2.external_identifiers IS '当前外部标识映射。';
COMMENT ON COLUMN wo_v2.external_identifiers.source_id IS '外部标识所属的来源命名空间。';
COMMENT ON COLUMN wo_v2.external_identifiers.kind IS '额外来源标识类型，如来源内部对象 ID 或必要别名；不统一外置主业务代码。';
COMMENT ON COLUMN wo_v2.external_identifiers.value IS '不能由主字段直接定位时所需的来源标识值，按字符串保留前导零。';
COMMENT ON COLUMN wo_v2.external_identifiers.product_id IS '指向产品的内部 ID；与 share_id 必须且只能有一项非空。';
COMMENT ON COLUMN wo_v2.external_identifiers.share_id IS '指向份额的内部 ID；与 product_id 必须且只能有一项非空。';
COMMENT ON TABLE wo_v2.inclusion_reasons IS '当前有效收录依据。';
COMMENT ON COLUMN wo_v2.inclusion_reasons.share_id IS '当前收录依据所属份额的内部 ID。';
COMMENT ON COLUMN wo_v2.inclusion_reasons.reason_type IS '有效收录依据类型，如热门条件、人工指定；撤销时删除对应记录。';
COMMENT ON TABLE wo_v2.observations IS '同源同日的净值/收益事实。';
COMMENT ON COLUMN wo_v2.observations.share_id IS '该条披露对应的份额内部 ID。';
COMMENT ON COLUMN wo_v2.observations.source_id IS '实际披露该条数据的来源键。';
COMMENT ON COLUMN wo_v2.observations.value_date IS '净值业务日或收益区间结束日，不是抓取时间或公告发布日期。';
COMMENT ON COLUMN wo_v2.observations.income_period_start IS '官方收益披露区间的起始日期；不适用或无法确认时为空。';
COMMENT ON COLUMN wo_v2.observations.income_basis IS '收益值口径，区分逐日值、区间合计和已日均值，避免重复平均。';
COMMENT ON COLUMN wo_v2.observations.unit_nav IS '官方单位净值；缺失或不适用时为空，不用零替代缺失。';
COMMENT ON COLUMN wo_v2.observations.cumulative_nav IS '官方累计净值；可为空，不自动等同于完整复权收益依据。';
COMMENT ON COLUMN wo_v2.observations.income_per_10k IS '官方万份收益披露值，须结合 income_basis 和披露区间解释。';
COMMENT ON COLUMN wo_v2.observations.official_yield_7d IS '官方七日年化，规范为比率保存，与自行计算的折算年化分开；可为空。';
COMMENT ON COLUMN wo_v2.observations.adjustment_verified_from IS '净值型同源调整信息已核实完整的覆盖起点，区间为该日起至 value_date 的左开右闭区间；未知为空，不从调整表为空推定无事项且不公开。';
COMMENT ON TABLE wo_v2.adjustments IS '计算必需的分红/拆分事实。';
COMMENT ON COLUMN wo_v2.adjustments.share_id IS '分红或拆分所影响份额的内部 ID。';
COMMENT ON COLUMN wo_v2.adjustments.source_id IS '披露该项调整信息的来源键。';
COMMENT ON COLUMN wo_v2.adjustments.effective_date IS '分红或拆分的业务生效日期，不是采集或公告发布日期。';
COMMENT ON COLUMN wo_v2.adjustments.event_type IS '调整类型，如现金分红或份额拆分。';
COMMENT ON COLUMN wo_v2.adjustments.cash_per_unit IS '事项前每份旧份额对应现金额；已确认无分红为 0，未知为空且不能签发完整调整覆盖。';
COMMENT ON COLUMN wo_v2.adjustments.split_factor IS '新份数/旧份数；已确认无拆分为 1，未知为空且不能签发完整调整覆盖。';
COMMENT ON TABLE wo_v2.current_metrics IS '固定指标的当前结果。';
COMMENT ON COLUMN wo_v2.current_metrics.share_id IS '指标所属份额的内部 ID。';
COMMENT ON COLUMN wo_v2.current_metrics.metric_code IS '首版固定指标的代码，区分日均、涨幅、各窗口年化和月持平次数。';
COMMENT ON COLUMN wo_v2.current_metrics.value IS '当前计算值；涨幅和年化用比率、万元日收益用元/万元·日、持平次数用计数；缺条件时为空。';
COMMENT ON COLUMN wo_v2.current_metrics.start_date IS '该项结果真实计算区间的起点日期；无法计算时可为空。';
COMMENT ON COLUMN wo_v2.current_metrics.end_date IS '该项结果真实计算区间的截止日期；不是任务运行时间。';
COMMENT ON COLUMN wo_v2.current_metrics.source_id IS '该项结果实际使用的数据来源；无法计算时可为空。';
COMMENT ON COLUMN wo_v2.current_metrics.unavailable_reason IS '缺少计算条件或不适用的原因；与真实零值、可用的窗口调整结果区分。';
RESET ROLE;
COMMIT;
